import React, { useRef, useState } from "react";
import { Link } from "react-router-dom";

// Assurez-vous que tous ces composants et assets existent dans votre structure de fichiers
import IndexNavbar from "components/Navbars/IndexNavbar.js";
import Footer from "components/Footers/Footer.js";
import NewsStack from "components/newsStack";
import PrettyCalendar from "components/calendar";

// Assets importés
import HeroImage from "assets/img/bg1.png";
import BannerImage from "assets/img/banniere.png";
import ressourcesImg from "assets/img/ressourcesImg.png";
import News1 from "assets/img/mbaye.png";
import News2 from "assets/img/newdeal.jpg";
import News3 from "assets/img/sim.jpg";

import site1_baobab from "assets/img/heritage.png";
import accel_png from "assets/img/accel.png";
import shirikia_png from "assets/img/shirikia.png";


import fatou from "assets/img/fatou.jpg";
import moussa from "assets/img/moussa.jpg";
import ndeye from "assets/img/ndeye.jpg";
import sankara from "assets/img/sankara.jpg";


// === DÉFINITION DU COMPOSANT ProfileCard ===
const ProfileCard = ({ name, image, text }) => (
  <div
    className="flex items-center p-4 min-w-0"
  >
    <div className="w-24 h-24 flex-shrink-0 mr-4 rounded-xl overflow-hidden">
      <img
        src={image}
        alt={name}
        className="w-full h-full object-cover"
      />
    </div>

    <div className="min-w-0">
      <h3 className="text-xl font-bold text-gray-900 mb-1 tracking-wider">{name}</h3>
      <p className="font-serif text-base text-gray-700 leading-relaxed">
        {text}
      </p>
    </div>
  </div>
);
// ===========================================


export default function Index() {
  const [bannerOffset, setBannerOffset] = useState(0);
  const twoColRef = useRef(null);

  // Données de remplacement pour les sites (la partie gauche)
  const frequentSites = [
    { title: "Site 1 - Baobab", description: "Le héro du projet...", image: site1_baobab },
    { title: "Site 2 - Data Map", description: "Plateforme donnée...", image: accel_png },
    { title: "Site 3 - Shirikia", description: "Accélérateur...", image: shirikia_png },
  ];

  // Données de remplacement pour les profils (la partie droite)
  const profiles = [
    { name: "FATOU DIA", image: fatou },
    { name: "MOUSSA FALL", image: moussa },
    { name: "NDEYE SENE", image: ndeye },
  ];

  return (
    <>
      <IndexNavbar fixed />

      {/* 1. HERO */}
      <section
        className="relative mt-16 md:mt-20 h-screen max-h-860-px flex items-center"
        style={{
          backgroundImage: `linear-gradient(rgba(107, 20, 15, 0.65), rgba(107, 20, 15, 0.25)), url(${HeroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center 30%",
          backgroundRepeat: "no-repeat",
        }}
      >
        <div className="container mx-auto relative z-10 flex flex-wrap items-center">
          <div className="w-full lg:w-6/12 px-4">
            <h1 className="font-bold text-5xl md:text-7xl text-white leading-tight">
              Dalal ak jàamm,
            </h1>
            <p className="mt-6 text-2xl md:text-3xl font-light text-white max-w-xl">
              Nassour !
            </p>
          </div>
        </div>
      </section>

      {/* 2. CALENDRIER + ACTUALITÉS */}
      <section className="relative bg-white py-16">
        <div className="container mx-auto px-4">
          <div ref={twoColRef} className="flex flex-col md:flex-row items-start md:space-x-8 space-y-8 md:space-y-0">
            <div className="w-full md:w-1/2 min-w-0">
              <h3 className="text-[#1c2b68] font-semibold text-xl mb-3">Un jour spécial pour ?</h3>
              <PrettyCalendar
                initialYear={2023}
                initialMonth={2}
                selectedDay={20}
                events={[
                  { date: "2023-02-20", label: "Anniversaire de Ousmane DIA" },
                  { date: "2023-02-16", label: "Réunion Produits" },
                ]}
              />
            </div>

            <div className="w-full md:w-1/2 min-w-0">
              <h3 className="text-[#1c2b68] font-semibold text-xl mb-3">Actualités</h3>
              <NewsStack
                items={[
                  { img: News2, href: "#" },
                  { img: News3, href: "#" },
                  { img: News1, href: "#" },
                ]}
              />
            </div>
          </div>
        </div>
      </section>

      {/* 3. BANNIÈRE & RESSOURCES (avec gestion du chevauchement complexe) */}
      <section
        className="relative w-full z-20"
        style={{ marginTop: "-500px" }}
      >
        <img
          src={BannerImage}
          alt="Bannière"
          className="w-full h-[500px] object-cover rounded-lg shadow-lg"
        />
      </section>
      <section className="relative w-full bg-white py-16">
        <div className="w-full">
          <img
            src={ressourcesImg}
            alt="Nouvelle section"
            className="rounded-lg shadow-lg object-cover"
            style={{
              width: "45%",
              height: "33%",
              marginLeft: "0",
              marginTop: "-350px"
            }}
          />
        </div>
      </section>

      <section className="w-full bg-white py-14">
        <div className="max-w-[1280px] mx-auto px-6 lg:px-12">
          <div className="flex gap-10 overflow-x-auto no-scrollbar snap-x">
            {/* LEFT: Sites fréquents (rétrécie à 1/6) */}
            <div className="flex-none w-1/6 min-w-[150px] snap-start">
              <h2 className="text-[#2d4ea3] font-extrabold tracking-wide text-[22px] mb-6">
                SITES FREQUENTS
              </h2>

              <div className="flex flex-col gap-5">
                {[site1_baobab, accel_png, shirikia_png].map((img, i) => (
                  <div
                    key={i}
                    className="w-full rounded-[16px] border-[3px] border-[#2f5ac8] overflow-hidden shadow-[0_4px_14px_rgba(0,0,0,0.06)]"
                  >
                    <img
                      src={img}
                      alt={`Site ${i + 1}`}
                      className="w-full h-[90px] object-cover"
                    />
                  </div>
                ))}
              </div>
            </div>

            {/* RIGHT: Bienvenue (plus large à 5/6) */}
            <div className="flex-none w-5/6 min-w-[900px] snap-start">
              <h2 className="text-[#2d4ea3] font-extrabold tracking-wide text-[28px] mb-6 text-center">
                BIENVENUE !
              </h2>

              <div className="bg-[#e5e5e7] rounded-[22px] px-8 py-8 shadow-[inset_0_2px_6px_rgba(0,0,0,0.05)]">
                {/* Fiche 1 */}
                <div className="flex items-start gap-6 pb-6 mb-6 border-b border-[#d7d7da]">
                  <div className="w-[220px] h-[110px] rounded-[18px] overflow-hidden shrink-0">
                    <img src={fatou} alt="FATOU DIA" className="w-full h-full object-cover" />
                  </div>
